import { documentsCatalog } from "./documents.catalog";

export interface RuleResult {
  documents: string[];
  taxes: string[];
  forms: string[];
}

export interface DuplicatInput {
  personType: string;
  proxy: string;
  duplicateReason: string;
  identityDocumentType: string;
}

export function buildDuplicatDosar(
  data: DuplicatInput
): RuleResult {
  const documents: string[] = [];
  const taxes: string[] = [];
  const forms: string[] = [];

  if (data.personType === "pf") {
    if (data.identityDocumentType === "ci") {
      documents.push("Carte identitate solicitant - față");
    }

    if (data.identityDocumentType === "cie") {
      documents.push("Carte identitate electronică solicitant - față");
      documents.push("Carte identitate electronică solicitant - spate");
      documents.push("Adeverință domiciliu");
    }
  }

  if (data.personType === "pj") {
    documents.push(documentsCatalog.cui_pj.name);
    documents.push(documentsCatalog.ci_reprezentant.name);
  }

  if (data.proxy === "da") {
    documents.push(documentsCatalog.imputernicire.name);
    documents.push(documentsCatalog.ci_imputernicit.name);
  }

  documents.push("Dovadă plată taxă duplicat certificat de înmatriculare");

  if (data.duplicateReason === "furat") {
    documents.push(documentsCatalog.dovada_furt.name);
  }

  if (data.duplicateReason === "deteriorat") {
    documents.push("Certificat de înmatriculare deteriorat");
  }

  forms.push("Cerere duplicat certificat de înmatriculare");

  if (data.duplicateReason === "pierdut") {
    forms.push("Declarație pierdere talon");
  }

  taxes.push("Taxă duplicat certificat de înmatriculare");

  return {
    documents,
    taxes,
    forms,
  };
}